def scrypt_mcf_hash(scrypt, password, salt=None):
    """Returns the MCF hash of the given password

    Supports both the libscrypt $s1$ format and the $7$ format.
    """
    if salt is None:
        salt = os.urandom(16)
    if scrypt.check(password, '$s1$' + salt):
        return '$s1$' + salt
    elif scrypt.check(password, '$7$' + salt):
        return '$7$' + salt
    else:
